INSERT INTO defects (project_id, code, name, defect_type, category, difficulty, description, root_cause, trigger_config, manifestation_config, fix_config, amplifier_config, freeze_rules, score_weight, estimated_fix_time, sort_order, is_active, provenance, template_bindings) VALUES
(0, 'mall-cpu-001', 'CPU 争用导致交易响应变慢', 'resource', 'cpu', 'easy', '正则规则引起 CPU 耗尽。 仅复现 CPU 争用现象；mall 没有该 WAF 正则，不能声称复现原始代码缺陷。', '来源描述：正则规则引起 CPU 耗尽。 模板根因需通过服务器验收确认。', '{"mode":"brain_instruction","prerequisites":["sandbox_ready","business_baseline_passed"],"combination":"single_until_separately_accepted"}'::jsonb, '{"expected":"正则规则引起 CPU 耗尽。","business_check":"记录商品浏览、注册及订单接口的失败与恢复证据；支付仍隔离","metrics_require_server_validation":true}'::jsonb, '{"required_evidence":["observed","repaired","revoked","cleanup","validated_at"],"must_validate_business_recovery":true,"timeout_is_not_user_fix":true}'::jsonb, '{"code":"mall-cpu-001","kind":"cpu","title":"CPU 争用导致交易响应变慢","target":{},"spec":{"scope":"pod","duration_sec":60,"cpu_percent":60},"trigger":{"type":"delay","delay_seconds":30},"recovery":[{"metric":"cpu_usage","service":"mall-portal","op":"lte","value":0.5}],"auto_revoke":true}'::jsonb, '{"sandbox_only":true,"max_duration_sec":120,"combination_requires_new_acceptance":true}'::jsonb, 10, 20, 100, false, '{"kind":"incident","url":"https://blog.cloudflare.com/details-of-the-cloudflare-outage-on-july-2-2019/","title":"Cloudflare 2019-07-02 CPU 耗尽事故","summary":"正则规则引起 CPU 耗尽。","reproduction_difference":"仅复现 CPU 争用现象；mall 没有该 WAF 正则，不能声称复现原始代码缺陷。","checked_at":"2026-10-04","confidence":"first_party_postmortem"}'::jsonb, '[{"executor":"pod_chaosblade","template_slug":"mall","target_workload":"mall-portal","status":"pending_validation","overrides":{},"evidence":{}}]'::jsonb),
(0, 'mall-memory-001', 'Redis 内存压力与业务写入失败', 'resource', 'memory', 'medium', '队列积压使 Redis 达到内存上限。 仅以 Pod 内存负载复现容量压力；不是 Redis 数据增长，也不等同 JVM 内存泄漏或原事故根因。', '来源描述：队列积压使 Redis 达到内存上限。 模板根因需通过服务器验收确认。', '{"mode":"brain_instruction","prerequisites":["sandbox_ready","business_baseline_passed"],"combination":"single_until_separately_accepted"}'::jsonb, '{"expected":"队列积压使 Redis 达到内存上限。","business_check":"记录商品浏览、注册及订单接口的失败与恢复证据；支付仍隔离","metrics_require_server_validation":true}'::jsonb, '{"required_evidence":["observed","repaired","revoked","cleanup","validated_at"],"must_validate_business_recovery":true,"timeout_is_not_user_fix":true}'::jsonb, '{"code":"mall-memory-001","kind":"memory","title":"Redis 内存压力与业务写入失败","target":{},"spec":{"scope":"pod","duration_sec":60,"mem_percent":50},"trigger":{"type":"delay","delay_seconds":30},"recovery":[{"metric":"mem_usage","service":"redis","op":"lte","value":268435456}],"auto_revoke":true}'::jsonb, '{"sandbox_only":true,"max_duration_sec":120,"combination_requires_new_acceptance":true}'::jsonb, 10, 20, 101, false, '{"kind":"incident","url":"https://slack.engineering/scaling-slacks-job-queue/","title":"Slack 任务队列生产事故","summary":"队列积压使 Redis 达到内存上限。","reproduction_difference":"仅以 Pod 内存负载复现容量压力；不是 Redis 数据增长，也不等同 JVM 内存泄漏或原事故根因。","checked_at":"2026-10-04","confidence":"first_party_postmortem"}'::jsonb, '[{"executor":"pod_chaosblade","template_slug":"mall","target_workload":"redis","status":"pending_validation","overrides":{},"evidence":{}}]'::jsonb),
(0, 'mall-network-001', '依赖网络延迟导致交易超时', 'config', 'network', 'medium', '网络中断触发数据库故障转移和长时间服务异常。 mall 为单数据库；只复现 Pod 网络退化，不复现跨机房故障转移。', '来源描述：网络中断触发数据库故障转移和长时间服务异常。 模板根因需通过服务器验收确认。', '{"mode":"brain_instruction","prerequisites":["sandbox_ready","business_baseline_passed"],"combination":"single_until_separately_accepted"}'::jsonb, '{"expected":"网络中断触发数据库故障转移和长时间服务异常。","business_check":"记录商品浏览、注册及订单接口的失败与恢复证据；支付仍隔离","metrics_require_server_validation":true}'::jsonb, '{"required_evidence":["observed","repaired","revoked","cleanup","validated_at"],"must_validate_business_recovery":true,"timeout_is_not_user_fix":true}'::jsonb, '{"code":"mall-network-001","kind":"network_delay","title":"依赖网络延迟导致交易超时","target":{},"spec":{"scope":"pod","duration_sec":60,"delay_millis":800},"trigger":{"type":"delay","delay_seconds":30},"recovery":[{"metric":"error_rate","service":"mall-portal","op":"lte","value":0.01}],"auto_revoke":true}'::jsonb, '{"sandbox_only":true,"max_duration_sec":120,"combination_requires_new_acceptance":true}'::jsonb, 10, 20, 102, false, '{"kind":"incident","url":"https://github.blog/news-insights/company-news/oct21-post-incident-analysis/","title":"GitHub 2018-10-21 网络分区事故","summary":"网络中断触发数据库故障转移和长时间服务异常。","reproduction_difference":"mall 为单数据库；只复现 Pod 网络退化，不复现跨机房故障转移。","checked_at":"2026-10-04","confidence":"first_party_postmortem"}'::jsonb, '[{"executor":"pod_chaosblade","template_slug":"mall","target_workload":"mall-portal","status":"pending_validation","overrides":{},"evidence":{}}]'::jsonb),
(0, 'mall-database-001', '数据库失联与连接获取超时', 'config', 'database', 'medium', 'MySQL 节点失效后报告连接池获取连接超时。 对 mall 单 MySQL Pod 注入丢包；不宣称当前 Druid 存在同一集群连接池缺陷。', '来源描述：MySQL 节点失效后报告连接池获取连接超时。 模板根因需通过服务器验收确认。', '{"mode":"brain_instruction","prerequisites":["sandbox_ready","business_baseline_passed"],"combination":"single_until_separately_accepted"}'::jsonb, '{"expected":"MySQL 节点失效后报告连接池获取连接超时。","business_check":"记录商品浏览、注册及订单接口的失败与恢复证据；支付仍隔离","metrics_require_server_validation":true}'::jsonb, '{"required_evidence":["observed","repaired","revoked","cleanup","validated_at"],"must_validate_business_recovery":true,"timeout_is_not_user_fix":true}'::jsonb, '{"code":"mall-database-001","kind":"network_loss","title":"数据库失联与连接获取超时","target":{},"spec":{"scope":"pod","duration_sec":60,"loss_percent":100},"trigger":{"type":"delay","delay_seconds":30},"recovery":[{"metric":"error_rate","service":"mall-portal","op":"lte","value":0.01}],"auto_revoke":true}'::jsonb, '{"sandbox_only":true,"max_duration_sec":120,"combination_requires_new_acceptance":true}'::jsonb, 10, 20, 103, false, '{"kind":"issue","url":"https://github.com/alibaba/druid/issues/4078","title":"Druid #4078 用户报告","summary":"MySQL 节点失效后报告连接池获取连接超时。","reproduction_difference":"对 mall 单 MySQL Pod 注入丢包；不宣称当前 Druid 存在同一集群连接池缺陷。","checked_at":"2026-10-04","confidence":"user_report"}'::jsonb, '[{"executor":"pod_chaosblade","template_slug":"mall","target_workload":"mysql","status":"pending_validation","overrides":{},"evidence":{}}]'::jsonb),
(0, 'mall-cache-001', '缓存容量上限导致写入拒绝', 'config', 'cache', 'medium', 'Redis 达到 maxmemory 后拒绝新增工作。 计划使用受限键前缀和可恢复 maxmemory 配置，尚未实现适配；不能把网络丢包当缓存容量问题。', '来源描述：Redis 达到 maxmemory 后拒绝新增工作。 模板根因需通过服务器验收确认。', '{"mode":"brain_instruction","prerequisites":["sandbox_ready","business_baseline_passed"],"combination":"single_until_separately_accepted"}'::jsonb, '{"expected":"Redis 达到 maxmemory 后拒绝新增工作。","business_check":"记录商品浏览、注册及订单接口的失败与恢复证据；支付仍隔离","metrics_require_server_validation":true}'::jsonb, '{"required_evidence":["observed","repaired","revoked","cleanup","validated_at"],"must_validate_business_recovery":true,"timeout_is_not_user_fix":true}'::jsonb, '{}'::jsonb, '{"sandbox_only":true,"max_duration_sec":120,"combination_requires_new_acceptance":true}'::jsonb, 10, 20, 104, false, '{"kind":"incident","url":"https://slack.engineering/scaling-slacks-job-queue/","title":"Slack 任务队列生产事故","summary":"Redis 达到 maxmemory 后拒绝新增工作。","reproduction_difference":"计划使用受限键前缀和可恢复 maxmemory 配置，尚未实现适配；不能把网络丢包当缓存容量问题。","checked_at":"2026-10-04","confidence":"first_party_postmortem"}'::jsonb, '[{"executor":"pending_adapter","template_slug":"mall","target_workload":"redis","status":"draft","overrides":{},"evidence":{}}]'::jsonb),
(0, 'mall-mq-001', '消费者退化与订单消息积压', 'architecture', 'mq', 'medium', '数据库争用拖慢消费者并造成队列持续积压。 将同类排队容量问题映射到 mall RabbitMQ；不是 Slack Redis 队列的根因复现，订单业务验收和消费者适配未完成。', '来源描述：数据库争用拖慢消费者并造成队列持续积压。 模板根因需通过服务器验收确认。', '{"mode":"brain_instruction","prerequisites":["sandbox_ready","business_baseline_passed"],"combination":"single_until_separately_accepted"}'::jsonb, '{"expected":"数据库争用拖慢消费者并造成队列持续积压。","business_check":"记录商品浏览、注册及订单接口的失败与恢复证据；支付仍隔离","metrics_require_server_validation":true}'::jsonb, '{"required_evidence":["observed","repaired","revoked","cleanup","validated_at"],"must_validate_business_recovery":true,"timeout_is_not_user_fix":true}'::jsonb, '{}'::jsonb, '{"sandbox_only":true,"max_duration_sec":120,"combination_requires_new_acceptance":true}'::jsonb, 10, 20, 105, false, '{"kind":"incident","url":"https://slack.engineering/scaling-slacks-job-queue/","title":"Slack 任务队列生产事故","summary":"数据库争用拖慢消费者并造成队列持续积压。","reproduction_difference":"将同类排队容量问题映射到 mall RabbitMQ；不是 Slack Redis 队列的根因复现，订单业务验收和消费者适配未完成。","checked_at":"2026-10-04","confidence":"first_party_postmortem"}'::jsonb, '[{"executor":"pending_adapter","template_slug":"mall","target_workload":"rabbitmq","status":"draft","overrides":{},"evidence":{}}]'::jsonb),
(0, 'mall-disk-001', '磁盘水位告警阻塞消息发布', 'resource', 'disk', 'medium', '磁盘告警下发布连接处于 blocked 状态。 计划暂调沙箱 RabbitMQ 水位并恢复原值；不填宿主机磁盘，不承诺复现历史残留连接细节，适配未完成。', '来源描述：磁盘告警下发布连接处于 blocked 状态。 模板根因需通过服务器验收确认。', '{"mode":"brain_instruction","prerequisites":["sandbox_ready","business_baseline_passed"],"combination":"single_until_separately_accepted"}'::jsonb, '{"expected":"磁盘告警下发布连接处于 blocked 状态。","business_check":"记录商品浏览、注册及订单接口的失败与恢复证据；支付仍隔离","metrics_require_server_validation":true}'::jsonb, '{"required_evidence":["observed","repaired","revoked","cleanup","validated_at"],"must_validate_business_recovery":true,"timeout_is_not_user_fix":true}'::jsonb, '{}'::jsonb, '{"sandbox_only":true,"max_duration_sec":120,"combination_requires_new_acceptance":true}'::jsonb, 10, 20, 106, false, '{"kind":"issue","url":"https://github.com/rabbitmq/rabbitmq-server/discussions/4627","title":"RabbitMQ #4627 真实复现与维护者讨论","summary":"磁盘告警下发布连接处于 blocked 状态。","reproduction_difference":"计划暂调沙箱 RabbitMQ 水位并恢复原值；不填宿主机磁盘，不承诺复现历史残留连接细节，适配未完成。","checked_at":"2026-10-04","confidence":"user_report"}'::jsonb, '[{"executor":"pending_adapter","template_slug":"mall","target_workload":"rabbitmq","status":"draft","overrides":{},"evidence":{}}]'::jsonb),
(0, 'mall-threadpool-001', '请求资源未释放导致线程池耗尽', 'code', 'threadpool', 'medium', '客户端断开后资源未释放，用户报告 Tomcat 无响应。 该报告未确认且已关闭为 not planned；mall 没有 MCP。当前仅为现象训练候选，必须另做可撤销代码覆盖和请求适配，不宣称存在同一漏洞。', '来源描述：客户端断开后资源未释放，用户报告 Tomcat 无响应。 模板根因需通过服务器验收确认。', '{"mode":"brain_instruction","prerequisites":["sandbox_ready","business_baseline_passed"],"combination":"single_until_separately_accepted"}'::jsonb, '{"expected":"客户端断开后资源未释放，用户报告 Tomcat 无响应。","business_check":"记录商品浏览、注册及订单接口的失败与恢复证据；支付仍隔离","metrics_require_server_validation":true}'::jsonb, '{"required_evidence":["observed","repaired","revoked","cleanup","validated_at"],"must_validate_business_recovery":true,"timeout_is_not_user_fix":true}'::jsonb, '{}'::jsonb, '{"sandbox_only":true,"max_duration_sec":120,"combination_requires_new_acceptance":true}'::jsonb, 10, 20, 107, false, '{"kind":"issue","url":"https://github.com/spring-projects/spring-ai/issues/6384","title":"Spring AI #6384 用户报告","summary":"客户端断开后资源未释放，用户报告 Tomcat 无响应。","reproduction_difference":"该报告未确认且已关闭为 not planned；mall 没有 MCP。当前仅为现象训练候选，必须另做可撤销代码覆盖和请求适配，不宣称存在同一漏洞。","checked_at":"2026-10-04","confidence":"user_report"}'::jsonb, '[{"executor":"pending_adapter","template_slug":"mall","target_workload":"mall-portal","status":"draft","overrides":{},"evidence":{}}]'::jsonb)
